import{_ as e,o as t,c as i,ai as s}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"[决策] 为何第一版不做微服务","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/industrial-digitalization/decisions/05-no-microservice.md","filePath":"tech-system/industrial-digitalization/decisions/05-no-microservice.md"}'),n={name:"tech-system/industrial-digitalization/decisions/05-no-microservice.md"};function r(l,a,d,o,c,h){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="决策-为何第一版不做微服务" tabindex="-1"><code>[决策]</code> 为何第一版不做微服务 <a class="header-anchor" href="#决策-为何第一版不做微服务" aria-label="Permalink to “[决策] 为何第一版不做微服务”">​</a></h1><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>状态</td><td>🔵 设计中</td></tr><tr><td>类型</td><td><code>[决策]</code> Rejected（当前阶段）</td></tr><tr><td>项目</td><td>Mini MES V0</td></tr><tr><td>证据</td><td>模块边界文档 + 后续单体仓库</td></tr></tbody></table><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>「IoT 服务 + MES 服务 + 网关服务」拆成多仓多进程，在架构图上很好看。</p><h2 id="判断" tabindex="-1">判断 <a class="header-anchor" href="#判断" aria-label="Permalink to “判断”">​</a></h2><p>V0 用 <strong>模块化单体（Modular Monolith）</strong>：一个 Spring Boot 进程内按包/模块划分 Gateway 接入适配、设备域、查询 API；Gateway 采集端可先独立小进程或同仓模块，但<strong>不</strong>上服务注册、拆库、分布式事务。</p><h2 id="暂不做微服务的原因" tabindex="-1">暂不做微服务的原因 <a class="header-anchor" href="#暂不做微服务的原因" aria-label="Permalink to “暂不做微服务的原因”">​</a></h2><ol><li>团队规模 = 1（实验室）；分布式排障成本由一人承担</li><li>领域边界尚未被实验打磨，过早拆服务会拆错</li><li>部署与联调时间应留给「采得到、看得见」</li></ol><h2 id="模块边界-单体内部先画清" tabindex="-1">模块边界（单体内部先画清） <a class="header-anchor" href="#模块边界-单体内部先画清" aria-label="Permalink to “模块边界（单体内部先画清）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>device      设备档案 / 在线</span></span>
<span class="line"><span>ingest      接收 Gateway HTTP</span></span>
<span class="line"><span>query       监控查询 API</span></span>
<span class="line"><span>（未来）workorder  工单——仍可先同进程</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>真要拆服务时，应按<strong>已被流量验证的边界</strong>拆，而不是按名词拆。</p><h2 id="重新评估触发" tabindex="-1">重新评估触发 <a class="header-anchor" href="#重新评估触发" aria-label="Permalink to “重新评估触发”">​</a></h2><ul><li>独立扩展/发布节奏明确不同</li><li>或 IoT 写入与 MES 事务隔离有强诉求且单体已被证伪</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><p><strong>第一版不做微服务；做清晰模块。</strong> 面试时可讲清「为什么不拆」，比「我用了微服务」更有说服力。</p>`,16)])])}const m=e(n,[["render",r]]);export{b as __pageData,m as default};
